        this.pendingRequests.delete(message.id);
        if (message.error) {
            const content = message.error.message ?? `Codex ${purpose} failed`;
            if (purpose === 'rateLimitsRead') {
                await this.onRuntimeEvent({ kind: 'unavailable', observedAt: Date.now() });
                return;
            }
            if (purpose === 'threadResume') {
                const missingSession = isCodexMissingThreadError(message.error, this.providerConversationId)
                    || isMissingSession('codex', { error: message.error, type: 'error' }, false);
                await this.onEvent({ content, missingSession, type: 'sessionFailed' });
                return;
            }
            await this.onEvent({ content, type: 'fatal' });
            return;
        }
        if (purpose === 'initialize') {
            await this.writeLine({ method: 'initialized', params: {} });
            await this.sendRequest('account/rateLimits/read', undefined, 'rateLimitsRead');
            if (this.providerConversationId) {
                await this.sendRequest('thread/resume', {
                    cwd: this.rootPath,
                    threadId: this.providerConversationId,
                }, 'threadResume');
                return;
            }
            await this.sendRequest('thread/start', { cwd: this.rootPath }, 'threadStart');
            return;
        }
        if (purpose === 'threadStart' || purpose === 'threadResume') {
            this.threadId = message.result?.thread?.id ?? message.result?.threadId ?? this.providerConversationId;
            if (!this.threadId) throw new Error('Codex app-server did not return a thread id');
            await this.onEvent({ conversationId: this.threadId, type: 'sessionStarted' });
            await this.sendMessage(this.initialPrompt);
            return;
        }
        if (purpose === 'rateLimitsRead') {
            const hasSingleBucket = !!message.result?.rateLimits && typeof message.result.rateLimits === 'object';
            const hasBuckets = !!message.result?.rateLimitsByLimitId
                && typeof message.result.rateLimitsByLimitId === 'object'
                && Object.keys(message.result.rateLimitsByLimitId).length > 0;
            await this.onRuntimeEvent(hasSingleBucket || hasBuckets
                ? { kind: 'snapshot', observedAt: Date.now(), payload: message.result }
                : { kind: 'unavailable', observedAt: Date.now() });
        }
    }

    async handleNotification(method, params) {
        if (method === 'turn/started') {
            this.activeItems.clear();
            this.assistantItemOrder = [];
            this.assistantStreams.clear();
            this.completedItemIds.clear();
            this.turnContextWindowUsage = undefined;
            this.activeTurnId = params.turn?.id ?? params.turnId;
            await this.onEvent({ turnId: this.activeTurnId, type: 'turnStarted' });
            return;
        }
        if (method === 'serverRequest/resolved') {
            await this.handleApprovalResolved(params);
            return;
        }
        if (method === 'item/started') {
            await this.handleItemStarted(method, params.item);
            return;
        }
        if (method === 'item/agentMessage/delta') {
            const trackedItem = await this.requireActiveItem(method, params.itemId, 'agentMessage');
            if (!trackedItem) return;
            trackedItem.assistantText = trackedItem.assistantText || params.delta.length > 0;
            trackedItem.bufferedAssistantText += params.delta;
            await this.flushAssistantStreams();
            return;
        }
        if (method === 'item/reasoning/summaryTextDelta') {
            await this.handleReasoningDelta(method, params, 'summary', params.summaryIndex);
            return;
        }
        if (method === 'item/reasoning/summaryPartAdded') {
            const trackedItem = await this.requireActiveItem(method, params.itemId, 'reasoning');
            if (!trackedItem) return;
            trackedItem.event = {
                ...trackedItem.event,
                summary: eventTextParts(trackedItem.event, 'summary', params.summaryIndex),
            };
            await this.emitEvent(trackedItem.event);
            return;
        }
        if (method === 'item/reasoning/textDelta') {
            await this.handleReasoningDelta(method, params, 'details', params.contentIndex);
            return;
        }
        if (method === 'item/commandExecution/outputDelta') {
            const trackedItem = await this.requireActiveItem(method, params.itemId, 'commandExecution');
            if (!trackedItem) return;
            trackedItem.event = { ...trackedItem.event, content: `${trackedItem.event.content}${params.delta}` };
            await this.emitEvent(trackedItem.event);
            return;
        }
        if (method === 'item/plan/delta') {
            const trackedItem = await this.requireActiveItem(method, params.itemId, 'plan');
            if (!trackedItem) return;
            trackedItem.event = { ...trackedItem.event, content: `${trackedItem.event.content}${params.delta}` };
            await this.emitEvent(trackedItem.event);
            return;
        }
        if (method === 'thread/tokenUsage/updated') {
            const usage = codexUsage(params);
            if (!usage) return;
            this.turnContextWindowUsage = codexContextWindowUsage(params);
            this.turnUsage = usage;
            await this.onEvent({ contextWindowUsage: this.turnContextWindowUsage, type: 'usage', usage });
            return;
        }
        if (method === 'account/rateLimits/updated') {
            await this.onRuntimeEvent({ kind: 'update', observedAt: Date.now(), payload: params });
            return;
        }
        if (method === 'item/completed') {
            await this.handleItemCompleted(method, params.item);
            return;
        }
        const normalizedSystemEvent = systemEvent(method, params);
        if (normalizedSystemEvent) {
            await this.emitEvent(normalizedSystemEvent);
            return;
        }
        if (method === 'error') {
            const content = params.error?.message ?? 'Codex turn failed';
            await this.emitEvent({
                content,
                label: 'Turn failure',
                providerItemId: `system:${this.activeTurnId ?? 'unknown-turn'}:error`,
                status: 'failed',
                type: 'system',
            });
            await this.onEvent({ content, type: 'fatal' });
            return;
        }
        if (method === 'turn/completed') {
            const error = params.turn?.status === 'failed'
                ? params.turn.error?.message ?? 'Codex turn failed'
                : null;
            if (error) {
                await this.emitEvent({
                    content: error,
                    label: 'Turn failure',
                    providerItemId: `system:${params.turn?.id ?? this.activeTurnId ?? 'unknown-turn'}:turn/completed`,
                    status: 'failed',
                    type: 'system',
                });
            }
            const completedTurnId = params.turn?.id ?? this.activeTurnId;
            await this.resolveApprovalsForTurn(completedTurnId);
            this.activeTurnId = null;
            const contextWindowUsage = this.turnContextWindowUsage;
            await this.onEvent({
                ...(contextWindowUsage !== undefined ? { contextWindowUsage } : {}),
                error,
                type: 'turnCompleted',
                usage: this.turnUsage,
            });
            this.turnContextWindowUsage = undefined;
            this.turnUsage = null;
            return;
        }
        if (method?.startsWith('item/') && typeof params.itemId === 'string') {
            await this.emitDiagnostic(method, null, params.itemId);
        }
    }

    async handleApprovalResolved(params) {
        const pendingApproval = this.pendingApprovals.get(params.requestId);
        if (!pendingApproval) return;
        if (params.threadId !== pendingApproval.approval.threadId) {
            throw new Error(`Mismatched Codex approval resolution thread id: ${params.threadId}`);
        }
        this.pendingApprovals.delete(params.requestId);
        await this.onEvent({ requestId: params.requestId, type: 'approvalResolved' });
    }

    async resolveApprovalsForTurn(turnId) {
        for (const [requestId, pendingApproval] of this.pendingApprovals) {
            if (pendingApproval.approval.turnId !== turnId) continue;
            this.pendingApprovals.delete(requestId);
            await this.onEvent({ requestId, type: 'approvalResolved' });
        }
    }

    async handleItemStarted(method, item) {
        if (!item || typeof item.id !== 'string' || typeof item.type !== 'string') {
            await this.emitDiagnostic(method, item?.type, item?.id);
            return;
        }
        if (this.activeItems.has(item.id) || this.completedItemIds.has(item.id)) {
            await this.emitDiagnostic(method, item.type, item.id);
            return;
        }
        const event = normalizeCodexEvent(item, 'inProgress');
        const knownNonEvent = CODEX_NON_EVENT_ITEM_TYPES.has(item.type);
        const trackedItem = {
            event,
            assistantCompleted: false,
            assistantText: false,
            bufferedAssistantText: '',
            item,
            itemType: item.type,
        };
        this.activeItems.set(item.id, trackedItem);
        if (item.type === 'agentMessage') {
            this.assistantItemOrder.push(item.id);
            this.assistantStreams.set(item.id, trackedItem);
            await this.onEvent({ itemId: item.id, type: 'assistantStarted' });
        }
        if (event) {
            await this.emitEvent(event);
            return;
        }
        if (!knownNonEvent) await this.emitDiagnostic(method, item.type, item.id);
    }

    async handleItemCompleted(method, item) {
        if (!item || typeof item.id !== 'string' || typeof item.type !== 'string') {
            await this.emitDiagnostic(method, item?.type, item?.id);
            return;
        }
        if (this.completedItemIds.has(item.id)) {
            await this.emitDiagnostic(method, item.type, item.id);
            return;
        }
        const trackedItem = this.activeItems.get(item.id);
        if (!trackedItem) await this.emitDiagnostic(method, item.type, item.id);
        if (trackedItem && trackedItem.itemType !== item.type) {
            await this.emitDiagnostic(method, item.type, item.id);
            return;
        }
        if (item.type === 'agentMessage' && trackedItem) {
            trackedItem.assistantCompleted = true;
            await this.flushAssistantStreams();
        }
        const changedPaths = codexChangedPaths(item, this.rootPath);
        if (changedPaths.length > 0) await this.onEvent({ paths: changedPaths, type: 'changedPaths' });
        const event = normalizeCodexEvent(item, 'completed');
        if (event) await this.emitEvent(event);
        if (!event && !CODEX_NON_EVENT_ITEM_TYPES.has(item.type) && trackedItem) {
            await this.emitDiagnostic(method, item.type, item.id);
        }
        this.activeItems.delete(item.id);
        this.completedItemIds.add(item.id);
    }

    async requireActiveItem(method, itemId, expectedType) {
        const trackedItem = this.activeItems.get(itemId);
        if (!trackedItem || trackedItem.itemType !== expectedType || this.completedItemIds.has(itemId)) {
            await this.emitDiagnostic(method, expectedType, itemId);

            return null;
        }

        return trackedItem;
    }

    async handleReasoningDelta(method, params, field, index) {
        const trackedItem = await this.requireActiveItem(method, params.itemId, 'reasoning');
        if (!trackedItem || !Number.isSafeInteger(index) || index < 0) {
            if (trackedItem) await this.emitDiagnostic(method, 'reasoning', params.itemId);
            return;
        }
        const parts = eventTextParts(trackedItem.event, field, index);
        parts[index] += params.delta;
        const event = { ...trackedItem.event, [field]: parts };
        trackedItem.event = {
            ...event,
            content: event.summary.length > 0 ? event.summary.join('\n\n') : event.details.join('\n\n'),
        };
        await this.emitEvent(trackedItem.event);
    }

    async flushAssistantStreams() {
        while (this.assistantItemOrder.length > 0) {
            const itemId = this.assistantItemOrder[0];
            const stream = this.assistantStreams.get(itemId);
            if (!stream) {
                this.assistantItemOrder.shift();
                continue;
            }
            if (stream.bufferedAssistantText.length > 0) {
                const content = stream.bufferedAssistantText;
                stream.bufferedAssistantText = '';
                await this.onEvent({ content, itemId, type: 'assistant' });
            }
            if (!stream.assistantCompleted) return;
            if (stream.assistantText) await this.onEvent({ content: '\n\n', itemId, type: 'assistant' });
            this.assistantStreams.delete(itemId);
            this.assistantItemOrder.shift();
        }
    }

    async emitEvent(event) {
        await this.onEvent({ event, type: 'event' });
    }

    async emitDiagnostic(method, itemType, itemId) {
        const event = diagnosticEvent(method, itemType, itemId, this.diagnosticSequence);
        this.diagnosticSequence += 1;
        await this.emitEvent(event);
    }
}

function createAgentStreamingAdapter(
    agent,
    writeLine,
    onEvent,
    rootPath,
    providerConversationId = null,
    onRuntimeEvent = async () => undefined,
) {
    if (agent === 'claude') return new ClaudeStreamingAdapter(writeLine, onEvent, rootPath, providerConversationId);
    if (agent === 'codex') {
        return new CodexStreamingAdapter(writeLine, onEvent, rootPath, providerConversationId, onRuntimeEvent);
    }

    throw new Error(`Agent profile does not support streaming: ${agent}`);
}

module.exports = { createAgentStreamingAdapter };

const { normalizeAgentTokenUsage } = require('../../../../shared/agent_usage_math.mjs');
const { normalizeChangedPaths, normalizedContent } = require('./agent_event_utils');

const CLAUDE_FILE_TOOLS = new Set(['Edit', 'MultiEdit', 'NotebookEdit', 'Write']);

/**
 * Claude speaks the same stream-json wire format on both the one-shot and the streaming path, so
 * every decoder here is shared by `agent_provider_protocol` and `ClaudeStreamingAdapter`. Keep it
 * that way: a decoder that lives in only one of them silently gives the two paths different output
 * for identical agent behaviour.
 */
function claudeAssistantText(event) {
    if (event.type !== 'assistant' || !Array.isArray(event.message?.content)) return '';

    return event.message.content
        .filter(({ type }) => type === 'text')
        .map(({ text }) => text)
        .filter((text) => typeof text === 'string')
        .join('');
}

function claudeChangedPaths(event, rootPath) {
    if (event.type !== 'assistant' || !Array.isArray(event.message?.content)) return [];

    const filePaths = event.message.content
        .filter((block) => block?.type === 'tool_use' && CLAUDE_FILE_TOOLS.has(block.name))
        .map(({ input, name }) => name === 'NotebookEdit' ? input?.notebook_path : input?.file_path);

    return normalizeChangedPaths(rootPath, filePaths);
}

/** Tool calls and their results, so the transcript shows what ran as well as what came back. */
function claudeTranscriptEvents(event) {
    if (!Array.isArray(event.message?.content)) return [];
    if (event.type === 'assistant') {
        return event.message.content
            .filter((block) => block?.type === 'tool_use')
            .map((block) => ({ content: JSON.stringify(block.input ?? {}), toolType: `tool.${block.name}` }));
    }
    if (event.type === 'user') {
        return event.message.content
            .filter((block) => block?.type === 'tool_result')
            .map((block) => ({ content: normalizedContent(block.content), toolType: 'tool.result' }))
            .filter(({ content }) => content !== null);
    }

    return [];
}

// Claude folds thinking into output_tokens, so reasoningTokens is always 0, and reports cache
// creation and cache reads as buckets alongside a cache-free input_tokens.
function claudeUsage(event) {
    if (event.type !== 'result' || !event.usage || typeof event.usage !== 'object' || Array.isArray(event.usage)) return null;

    return normalizeAgentTokenUsage({
        cachedInputTokens: (event.usage.cache_creation_input_tokens ?? 0) + (event.usage.cache_read_input_tokens ?? 0),
        costUsd: event.total_cost_usd,
        inputTokens: event.usage.input_tokens,
        outputTokens: event.usage.output_tokens,
        reasoningTokens: 0,
    });
}

module.exports = { claudeAssistantText, claudeChangedPaths, claudeTranscriptEvents, claudeUsage };

import type { AgentConversation, AgentTokenUsage, Card, ProjectSnapshot } from '../../data/data_types'
import { sumAgentTokenUsage } from '../../../../shared/agent_usage_math.mjs'

export { sumAgentTokenUsage }

export interface AgentUsageVersion {
    name: string
    usage: AgentTokenUsage
}

export interface AgentFileChangeUsage {
    deletions: number
    insertions: number
}

export interface ProjectAgentUsage {
    archived: AgentUsageVersion
    current: AgentUsageVersion
    project: AgentTokenUsage
    releases: AgentUsageVersion[]
}

export function cardAgentTokenUsage(source: AgentConversation[] | Card): AgentTokenUsage {
    const conversations = Array.isArray(source) ? source : source.agentConversations

    return sumAgentTokenUsage(conversations.map(({ usage }) => usage))
}

/** Aggregate loaded conversations belonging to one action on one card. */
export function actionCardAgentTokenUsage(conversations: AgentConversation[], actionId: string, cardInternalId: string): AgentTokenUsage {
    const matchingUsage = conversations
        .filter((conversation) => conversation.actionId === actionId && conversation.cardInternalId === cardInternalId)
        .map(({ usage }) => usage)

    return sumAgentTokenUsage(matchingUsage)
}

/** Sum completed provider patches in one canonical conversation. */
export function conversationFileChangeUsage(conversation: AgentConversation | null): AgentFileChangeUsage | null {
    if (!conversation) return null
    let countedEvents = 0
    let deletions = 0
    let insertions = 0
    for (const entry of conversation.entries) {
        if (entry.kind !== 'event' || entry.type !== 'fileChange' || entry.status !== 'completed') continue
        const { deletions: eventDeletions, insertions: eventInsertions } = entry
        if (typeof eventDeletions !== 'number' || !Number.isSafeInteger(eventDeletions) || eventDeletions < 0) continue
        if (typeof eventInsertions !== 'number' || !Number.isSafeInteger(eventInsertions) || eventInsertions < 0) continue

        countedEvents += 1
        deletions += eventDeletions
        insertions += eventInsertions
    }

    return countedEvents > 0 ? { deletions, insertions } : null
}

function releaseName(cardPath: string, releasesFolder: string) {
    const normalizedReleasesFolder = releasesFolder.replace(/\\/gu, '/').replace(/^\/+|\/+$/gu, '')
    const releasesPrefix = `${normalizedReleasesFolder}/`
    const normalizedCardPath = cardPath.replace(/\\/gu, '/')
    if (!normalizedCardPath.startsWith(releasesPrefix)) return null

    const releaseSegments = normalizedCardPath.slice(releasesPrefix.length).split('/')

    return releaseSegments.length >= 2 && releaseSegments[0].length > 0 ? releaseSegments[0] : null
}

/** Aggregate loaded agent conversations by current board, archived release, and project. */
function isInsideFolder(cardPath: string, folder: string) {
    const normalizedFolder = folder.replace(/\\/gu, '/').replace(/^\/+|\/+$/gu, '')
    const normalizedCardPath = cardPath.replace(/\\/gu, '/')

    return normalizedCardPath.startsWith(`${normalizedFolder}/`)
}

/** Aggregate loaded agent conversations by current board, archived cards, releases, and project. */
export function projectAgentTokenUsage(
    snapshot: ProjectSnapshot | null,
    releasesFolder: string,
    archivedFolder: string,
): ProjectAgentUsage {
    const activeCards = snapshot?.activeCards ?? []
    const backgroundCards = snapshot?.backgroundCards ?? []
    const currentUsage = sumAgentTokenUsage(activeCards.map(({ agentConversations }) => cardAgentTokenUsage(agentConversations)))
    const archivedUsage = sumAgentTokenUsage(
        backgroundCards
            .filter((card) => isInsideFolder(card.path, archivedFolder))
            .map(({ agentConversations }) => cardAgentTokenUsage(agentConversations)),
    )
    const releaseCards = new Map<string, Card[]>()

    for (const card of backgroundCards) {
        const name = releaseName(card.path, releasesFolder)
        if (!name) continue

        releaseCards.set(name, [...(releaseCards.get(name) ?? []), card])
    }
    const releases = [...releaseCards.entries()]
        .map(([name, cards]) => ({
            name,
            usage: sumAgentTokenUsage(cards.map(({ agentConversations }) => cardAgentTokenUsage(agentConversations))),
        }))
        .sort((left, right) => left.name.localeCompare(right.name))
    const project = sumAgentTokenUsage([currentUsage, archivedUsage, ...releases.map(({ usage }) => usage)])

    return {
        archived: { name: 'Archived', usage: archivedUsage },
        current: { name: 'Current', usage: currentUsage },
        project,
        releases,
    }
}

import {
    buildReleaseMoves,
    findArchiveAssetPaths,
    findReleaseActivityPaths,
    validateReleaseName,
} from '../data/release_archiving'
import { statusOf } from '../data/card_ordering'
import { projectAccessService } from './project/project_access_service'
import type { MarkdownFile, MoveFile, ProjectAsset, ProjectReference, ProjectSnapshot, ReleaseBranchCandidate } from '../data/data_types'
import { type RequiredDataServiceDependencies } from './data/data_service_context'
import { markdownParsingService } from './data/markdown_parsing_service'
import { telemetryService } from './telemetry/telemetry_service'

export interface ReleaseOperationsDeps {
    applyMoves(moves: MoveFile[], workingFolder: string): void
    dispatchChanged(): void
    files(): MarkdownFile[]
    project(): ProjectReference | null
    requireDependencies(): RequiredDataServiceDependencies
    snapshot(): ProjectSnapshot | null
}

function requireNoAssignedWorktrees(activeCards: ProjectSnapshot['activeCards']) {
    const assignedCardIds = activeCards
        .filter((card) => card.header.worktree !== null && card.header.worktree !== undefined)
        .map((card) => card.header.id)
    if (assignedCardIds.length > 0) {
        throw new Error(`Cannot complete release. Unassign worktrees from cards: ${assignedCardIds.join(', ')}.`)
    }
}

export class ReleaseOperations {
    private readonly dependencies: ReleaseOperationsDeps
    private readonly flushPendingCommitBatch: () => Promise<void>

    constructor(
        dependencies: ReleaseOperationsDeps,
        flushPendingCommitBatch: () => Promise<void>,
    ) {
        this.dependencies = dependencies
        this.flushPendingCommitBatch = flushPendingCommitBatch
    }

    async getReleaseBranchCandidates(): Promise<ReleaseBranchCandidate[]> {
        const { config, storage } = this.dependencies.requireDependencies()
        const currentProject = this.dependencies.project()
        if (!currentProject) throw new Error('Cannot load release branches before a project is open')

        const activeCards = this.dependencies.snapshot()?.activeCards ?? []
        requireNoAssignedWorktrees(activeCards)
        if (!storage.deleteLocalBranch) return []

        const finalState = config.states.at(-1)
        if (!finalState) throw new Error('Cannot complete a release without configured states')
        const localBranches = new Set((await storage.listBranches(currentProject)).map(({ name }) => name))

        return activeCards
            .filter((card) => statusOf(card) === finalState.state)
            .filter((card) => !!card.header.branch && localBranches.has(card.header.branch))
            .filter((card) => card.header.branch !== currentProject.branch && !card.header.branch?.startsWith('md2/parking/'))
            .map((card) => {
                const branchName = card.header.branch
                if (!branchName) throw new Error(`Release branch identity is missing: ${card.header.id}`)

                return { branchName, cardId: card.header.id, cardPath: card.path }
            })
    }

    async completeRelease(releaseName: string, selectedBranchNames: string[]) {
        projectAccessService.requireWritable()
        const { config, storage } = this.dependencies.requireDependencies()
        const currentProject = this.dependencies.project()
        if (!currentProject) throw new Error('Cannot complete a release before a project is open')

        const safeReleaseName = validateReleaseName(releaseName)
        await this.flushPendingCommitBatch()

        const finalState = config.states.at(-1)
        if (!finalState) throw new Error('Cannot complete a release without configured states')

        const activeCards = this.dependencies.snapshot()?.activeCards ?? []
        requireNoAssignedWorktrees(activeCards)
        const releaseCards = activeCards.filter((card) => statusOf(card) === finalState.state)
        if (releaseCards.length === 0) throw new Error(`Cannot complete a release without cards in the final column: ${finalState.state}`)

        const candidates = await this.getReleaseBranchCandidates()
        const candidateByBranch = new Map(candidates.map((candidate) => [candidate.branchName, candidate]))
        const uniqueSelectedBranchNames = [...new Set(selectedBranchNames)]
        const invalidBranch = uniqueSelectedBranchNames.find((branchName) => !candidateByBranch.has(branchName))
        if (invalidBranch) throw new Error(`Branch is not available for this release: ${invalidBranch}`)
        if (uniqueSelectedBranchNames.length > 0 && !storage.deleteLocalBranch) {
            throw new Error('Local branch deletion is not available')
        }

        const repositoryFiles = this.dependencies.snapshot()?.repositoryFiles ?? []
        const files = this.dependencies.files()
        const assetPaths = findArchiveAssetPaths(files, releaseCards)
        const assetFiles = await this.loadReleaseAssets(assetPaths)
        const activityPaths = findReleaseActivityPaths(releaseCards, config.projectFolder, repositoryFiles)
        const activityFiles = await this.loadReleaseActivityFiles(activityPaths)
        const moves = buildReleaseMoves(
            [...files, ...assetFiles],
            releaseCards,
            config.projectFolder,
            config.releasesFolder,
            safeReleaseName,
            repositoryFiles,
            activityFiles,
        )
        await storage.moveFiles({
            branch: currentProject.branch,
            message: `Complete release ${safeReleaseName}`,
            moves,
        })

        if (config.pushMode === 'auto') await storage.push(currentProject)

        const deletedCandidates: ReleaseBranchCandidate[] = []
        const cleanupFailures: string[] = []
        for (const branchName of uniqueSelectedBranchNames) {
            try {
                if (!storage.deleteLocalBranch) throw new Error('Local branch deletion is not available')
                await storage.deleteLocalBranch(currentProject, branchName)
                const candidate = candidateByBranch.get(branchName)
                if (!candidate) throw new Error(`Release branch candidate disappeared: ${branchName}`)
                deletedCandidates.push(candidate)
            } catch (error) {
                const message = error instanceof Error ? error.message : String(error)
                cleanupFailures.push(`${branchName}: ${message}`)
            }
        }

        let clearedFiles: MarkdownFile[] = []
        if (deletedCandidates.length > 0) {
            try {
                const preparedClearedFiles = deletedCandidates.map((candidate) => {
                    const move = moves.find(({ fromPath }) => fromPath === candidate.cardPath)
                    if (!move) throw new Error(`Released card move is missing: ${candidate.cardId}`)

                    return { content: markdownParsingService.setBranch(move.content, null), path: move.toPath }
                })
                const committedFiles = await storage.commit({
                    branch: currentProject.branch,
                    files: preparedClearedFiles,
                    message: 'Clear deleted release branches',
                })
                clearedFiles = committedFiles.length > 0 ? committedFiles : preparedClearedFiles
                if (config.pushMode === 'auto') await storage.push(currentProject)
            } catch (error) {
                const message = error instanceof Error ? error.message : String(error)
                cleanupFailures.push(`branch metadata: ${message}`)
            }
        }

        const clearedFilesByPath = new Map(clearedFiles.map((file) => [file.path, file]))
        const appliedMoves = moves.map((move) => {
            const clearedFile = clearedFilesByPath.get(move.toPath)
            return clearedFile ? { ...move, content: clearedFile.content, sha: clearedFile.sha } : move
        })
        this.dependencies.applyMoves(appliedMoves, config.workingFolder)
        this.dependencies.dispatchChanged()
        telemetryService.trackEvent('complete_release')

        if (cleanupFailures.length > 0) {
            throw new Error(`Release completed, but branch cleanup failed: ${cleanupFailures.join('; ')}`)
        }

        return this.dependencies.snapshot()
    }

    private async loadReleaseAssets(assetPaths: string[]) {
        if (assetPaths.length === 0) return []

        const { storage } = this.dependencies.requireDependencies()
        const currentProject = this.dependencies.project()
        if (!currentProject) throw new Error('Cannot load release assets before a project is open')
        if (!storage.loadProjectAsset) throw new Error('Project asset loading is not available')

        const assets: ProjectAsset[] = []
        for (const assetPath of assetPaths) {
            assets.push(await storage.loadProjectAsset(currentProject, assetPath))
        }

        return assets.map((asset): MarkdownFile => ({
            content: asset.content,
            encoding: asset.encoding,
            path: asset.path,
        }))
    }

    private async loadReleaseActivityFiles(activityPaths: string[]) {
        if (activityPaths.length === 0) return []

        const { storage } = this.dependencies.requireDependencies()
        const currentProject = this.dependencies.project()
        if (!currentProject) throw new Error('Cannot load release activity before a project is open')
        if (!storage.loadTextFile) throw new Error('Repository text file loading is not available')

        const activityFiles: MarkdownFile[] = []
        for (const activityPath of activityPaths) {
            activityFiles.push(await storage.loadTextFile(currentProject, activityPath))
        }

        return activityFiles
    }
}

