};

const {
    activityConversationReference,
    upsertActivityConversation,
    upsertAndCommitActivityConversation,
} = require('../activity/activity_files');

function requireActivityRequest(request) {
    if (!request?.activityProject) throw new Error('Missing agent activityProject');
    if (!request.activityOrigin) throw new Error('Missing agent activityOrigin');
    if (typeof request.projectFolder !== 'string') throw new Error('Missing agent projectFolder');

    return request;
}

function conversationReference(request, conversationId) {
    const activityRequest = requireActivityRequest(request);

    return activityConversationReference(activityRequest.projectFolder, activityRequest.activityOrigin, conversationId);
}

async function persistTerminalConversation(run) {
    const request = requireActivityRequest(run.request);
    await upsertAndCommitActivityConversation(
        request.activityProject,
        request.projectFolder,
        request.activityOrigin,
        run.conversation,
        `Update ${request.activityOrigin.kind} activity`,
    );
}

async function persistConversationCheckpoint(run) {
    const request = requireActivityRequest(run.request);
    await upsertActivityConversation(
        request.activityProject,
        request.projectFolder,
        request.activityOrigin,
        run.conversation,
    );
}

module.exports = {
    conversationReference,
    persistConversation: persistTerminalConversation,
    persistConversationCheckpoint,
    persistTerminalConversation,
};

const crypto = require('node:crypto');
const path = require('node:path');
const crossSpawn = require('cross-spawn');

const {
    accumulateUsage,
    createConversation,
    createEventEntry,
    createMessageEntry,
    snapshotConversation,
    transitionConversationStatus,
    updateProviderSession,
} = require('./agent_conversation');
const {
    conversationReference,
    persistConversation,
    persistConversationCheckpoint,
} = require('./agent_conversation_persistence');
const { AgentExecutableResolver } = require('./agent_executable_availability');
const { createAgentEnvironment } = require('./agent_environment');
const { ClaudeUsagePoller } = require('./claude_usage_poller');
const { diagnoseCodexCacheError, isCodexCacheError } = require('./agent_codex_cache_diagnostic');
const { logAgentEvent } = require('./agent_file_logger');
const agentInteractions = require('./agent_run_interactions');
const {
    attachRunProtocol,
    createRun,
    createRunResult,
    emitRunEvent,
} = require('./agent_run_state');
const {
    appendAssistantOutput,
    completeAssistantOutput,
    lastMessageEntry,
    nextConversationSequence,
    nextRunSequence,
} = require('./agent_run_transcript');
const {
    readOptionalString,
    requireCommand,
    requireProjectFolder,
    requireString,
} = require('./agent_run_validation');
const { redactSecrets } = require('./agent_secret_redaction');
const { filterCompleteStderrLines, isHiddenStderrLine, stripAnsi } = require('./agent_stderr_filter');
const { STREAMING_EVENT_HANDLERS } = require('./agent_streaming_event_handlers');
const { terminateProcessTree } = require('../process_tree');
const { assertGitRoot, ensureInsideRoot, requireRootPath } = require('../../git/git_commands');

const AGENT_FINISH_GRACE_MS = 5_000;

class AgentRunnerService {
    constructor(dependencies = {}) {
        this.claudeRuntimeService = dependencies.claudeRuntimeService ?? null;
        this.codexRuntimeService = dependencies.codexRuntimeService ?? null;
        this.usageMetricsService = dependencies.usageMetricsService ?? null;
        this.persistConversation = dependencies.persistConversation
            ?? dependencies.persistTerminalConversation
            ?? persistConversation;
        this.persistConversationCheckpoint = dependencies.persistConversationCheckpoint
            ?? persistConversationCheckpoint;
        this.executableResolver = dependencies.executableResolver ?? new AgentExecutableResolver();
        this.claudeUsagePoller = dependencies.claudeUsagePoller ?? new ClaudeUsagePoller({
            executableResolver: this.executableResolver,
            onRuntimeEvent: (event) => this.handleClaudeRuntimeEvent(event),
        });
        this.diagnoseCodexCacheError = dependencies.diagnoseCodexCacheError ?? diagnoseCodexCacheError;
        this.clearTimeout = dependencies.clearTimeout ?? clearTimeout;
        this.setTimeout = dependencies.setTimeout ?? setTimeout;
        this.terminateProcessTree = dependencies.terminateProcessTree ?? terminateProcessTree;
        this.handleFinishTimeout = this.handleFinishTimeout.bind(this);
        this.processes = new Map();
        this.runningConversationIds = new Set();
    }

    async run(project, request, onEvent) {
        let resolveCompletion;
        let rejectCompletion;
        const completion = new Promise((resolve, reject) => {
            resolveCompletion = resolve;
            rejectCompletion = reject;
        });
        const onComplete = (exitCode, run) => resolveCompletion(createRunResult(request, exitCode, run));
        const onCompletionError = (error) => rejectCompletion(error);

        await this.start(project, request, onEvent, onComplete, onCompletionError);

        return completion;
    }

    async start(project, requestValue, onEvent, onComplete, onCompletionError) {
        const request = {
            activityOrigin: { kind: 'project' },
            activityProject: project,
            ...requestValue,
        };
        const rootPath = requireRootPath(project);
        await assertGitRoot(rootPath);
        const command = requireCommand(request?.command);
        readOptionalString(request?.actionId, 'actionId');
        const cardPath = readOptionalString(request?.cardPath, 'cardPath');
        const prompt = requireString(request?.prompt, 'prompt');
        const agent = requireString(request?.agent ?? 'generic', 'agent');
        const streaming = request.streaming === true;
        requireProjectFolder(request?.projectFolder);
        if (cardPath) ensureInsideRoot(rootPath, path.join(rootPath, cardPath));
        const usageMetricsDestination = { projectFolder: request.projectFolder, rootPath };

        const id = `agent-turn-${crypto.randomUUID()}`;
        const startedAt = new Date().toISOString();
        const conversationId = request.conversation?.id ?? request.conversationId ?? `agent-${crypto.randomUUID()}`;
        const reference = request.reference ?? conversationReference(request, conversationId);
        const conversation = createConversation(request, conversationId, startedAt, reference);
        let nextSequence = nextConversationSequence(conversation);
        if (this.runningConversationIds.has(conversation.id)) throw new Error(`Agent conversation already has a running turn: ${conversation.id}`);
        const lastMessage = lastMessageEntry(conversation);
        if (request.reuseLastUserMessage) {
            if (lastMessage?.role !== 'user' || lastMessage.content !== prompt) throw new Error('Missing failed-turn user message for agent retry');
        } else {
            conversation.entries.push(createMessageEntry(`${id}-user`, 'user', prompt, startedAt, undefined, nextSequence));
            nextSequence += 1;
        }
        const [configuredExecutable, ...configuredArguments] = command;
        const environment = createAgentEnvironment(process.env);
        const resolvedExecutable = await this.executableResolver.find(configuredExecutable, { cwd: rootPath, env: environment });
        const executable = resolvedExecutable ?? configuredExecutable;
        const argumentsList = streaming ? configuredArguments : [...configuredArguments, prompt];
        const child = crossSpawn(executable, argumentsList, {
            cwd: rootPath,
            detached: process.platform !== 'win32',
            env: environment,
            stdio: ['pipe', 'pipe', 'pipe'],
            // windowsHide: true,
        });
        logAgentEvent('[agent:start]', {
            arguments: configuredArguments,
            cwd: rootPath,
            actionRunId: request.actionRunId ?? null,
            executable,
            pid: child.pid,
            runId: id,
            startedAt,
        });
        const run = createRun({
            agent,
            child,
            conversation,
            environment,
            executable,
            id,
            nextSequence,
            onComplete,
            onCompletionError,
            onEvent,
            reference,
            request,
            startedAt,
            streaming,
            usageMetricsDestination,
        });
        attachRunProtocol(run, {
            onCodexRuntimeEvent: (event) => this.handleCodexRuntimeEvent(event, usageMetricsDestination),
            onMalformedOutput: (line) => this.handleMalformedOutput(id, line),
            onProviderEvent: (event) => this.handleProviderEvent(id, event),
            onStreamingEvent: (event) => this.handleStreamingEvent(id, event),
            onStreamingLine: (line) => this.handleStreamingLine(id, line),
            providerConversationId: request.providerConversationId,
            rootPath,
        });
        this.processes.set(id, run);
        this.runningConversationIds.add(conversation.id);

        child.stdout.on('data', (chunk) => this.handleOutput(id, 'stdout', chunk));
        child.stderr.on('data', (chunk) => this.handleOutput(id, 'stderr', chunk));
        child.on('error', (error) => this.handleError(id, error));
        child.stdin.on('error', (error) => this.handleError(id, error));
        child.on('close', (exitCode) => {
            void this.handleClose(id, exitCode ?? 1).finally(run.resolveClosed);
        });
        if (streaming) {
            const initialPrompt = typeof request.contextInput === 'string' && request.contextInput.length > 0
                ? `${request.contextInput}\n\n[User]\n\n${prompt}`
                : prompt;
            try {
                await run.streamingAdapter.start(initialPrompt);
            } catch (error) {
                this.failStreamingRun(run, error);
            }
        } else {
            if (typeof request.contextInput === 'string' && request.contextInput.length > 0) child.stdin.write(request.contextInput);
            child.stdin.end();
        }
        const userMessage = lastMessageEntry(conversation);
        if (!userMessage || userMessage.role !== 'user') throw new Error('Missing current agent user message');
        const conversationSnapshot = snapshotConversation(conversation);
        emitRunEvent(run, {
            continued: !!request.conversation,
            conversation: conversationSnapshot,
            type: 'started',
        });

        return { conversation: conversationSnapshot, reference, runId: id };
    }

    stop(runId) {
        const run = this.requireRun(runId);
        run.cancelled = true;
        run.queuedMessage = null;
        transitionConversationStatus(run.conversation, 'cancelled', new Date().toISOString());
        this.clearFinishTimeout(run);

        return this.ensureTermination(run);
    }

    suspend(runId) {
        const run = this.requireRun(runId);
        run.suspended = true;
        run.queuedMessage = null;
        this.clearFinishTimeout(run);

        return this.ensureTermination(run);
    }

    beginQueuedMessageDraft(runId) {
        return agentInteractions.beginQueuedMessageDraft(this.requireRun(runId));
    }

    setQueuedMessage(runId, sessionId, content, revision) {
        return agentInteractions.setQueuedMessage(this.requireRun(runId), sessionId, content, revision);
    }

    sendQueuedMessage(runId, sessionId, revision) {
        return agentInteractions.sendQueuedMessage(this, this.requireRun(runId), sessionId, revision);
    }

    sendMessage(runId, content) {
        return agentInteractions.sendMessage(this, this.requireStreamingRun(runId), content);
    }

    sendStreamingMessage(run, content) {
        return agentInteractions.sendStreamingMessage(this, run, content);
    }

    answerQuestion(runId, requestId, answers) {
        return agentInteractions.answerQuestion(this, this.requireStreamingRun(runId), requestId, answers);
    }

    answerApproval(runId, requestId, decision) {
        return agentInteractions.answerApproval(this, this.requireStreamingRun(runId), requestId, decision);
    }

    finish(runId) {
        const run = this.requireStreamingRun(runId);
        run.finishing = true;
        run.queuedMessage = null;
        if (!run.turnActive || run.waitingForQuestion) this.beginFinishShutdown(run);
    }

    beginFinishShutdown(run) {
        if (run.finishTimeout !== null && run.finishTimeout !== undefined) return;
        run.finishTimeout = this.setTimeout(this.handleFinishTimeout, AGENT_FINISH_GRACE_MS, run.id);
        run.child.stdin.end();
    }

    clearFinishTimeout(run) {
        if (run.finishTimeout === null || run.finishTimeout === undefined) return;
        this.clearTimeout(run.finishTimeout);
        run.finishTimeout = null;
    }

    async handleFinishTimeout(runId) {
        const run = this.processes.get(runId);
        if (!run) return;
        run.finishTimeout = null;
        console.warn('[agent:finish-timeout]', {
            graceMs: AGENT_FINISH_GRACE_MS,
            pid: run.child.pid,
            runId,
            timestamp: new Date().toISOString(),
        });
        try {
            run.finishForced = await this.ensureTermination(run);
        } catch (error) {
            this.handleError(runId, error);
        }
    }

    stopAll() {
        this.claudeUsagePoller.stop();
        const completions = [];
        for (const run of this.processes.values()) {
            run.cancelled = true;
            transitionConversationStatus(run.conversation, 'cancelled', new Date().toISOString());
            this.clearFinishTimeout(run);
            completions.push(Promise.all([this.ensureTermination(run), run.closed]));
        }

        return Promise.all(completions);
    }

    ensureTermination(run) {
        run.termination ??= this.terminateProcessTree(run.child);

        return run.termination;
    }

    async handleCodexRuntimeEvent(event, destination) {
        if (!this.codexRuntimeService) return;
        if (event.kind === 'unavailable') {
            this.codexRuntimeService.publishUnavailable(event.observedAt);
            return;
        }
        const accepted = this.codexRuntimeService.publishRateLimits(event.payload, event.observedAt, event.kind === 'update');
        if (!accepted || !this.usageMetricsService) return;
        await this.usageMetricsService.recordAccountUsage(destination, 'codex', this.codexRuntimeService.getSnapshot());
    }

    async handleClaudeRuntimeEvent(event) {
        if (!this.claudeRuntimeService) return;
        if (event.kind === 'unavailable') {
            this.claudeRuntimeService.publishUnavailable(event.observedAt);
            return;
        }
        const accepted = this.claudeRuntimeService.publishRateLimits(event.payload, event.observedAt);
        if (!accepted || !this.usageMetricsService) return;
        const snapshot = this.claudeRuntimeService.getSnapshot();
        await Promise.all(event.destinations.map((destination) => (
            this.usageMetricsService.recordAccountUsage(destination, 'claude', snapshot)
        )));
    }

    requestClaudeUsagePoll(run) {
        if (run.agent === 'claude' && run.stdout.trim().length > 0) {
            this.claudeUsagePoller.requestPoll(run.usageMetricsDestination);
        }
    }

    recordTokenUsage(run, usage, recordedAt) {
        if (!this.usageMetricsService) return false;

        return this.usageMetricsService.recordTokenUsage(
            run.usageMetricsDestination,
            run.agent,
            usage,
            Date.parse(recordedAt),
        );
    }

    handleOutput(runId, channel, chunk) {
        const run = this.processes.get(runId);
        if (!run) return;

        const content = chunk.toString();
        if (channel === 'stdout' && run.protocolLines) {
            run.protocolLines.push(chunk);
            return;
        }
        if (channel === 'stdout' && run.parser) {
            run.parser.push(chunk);
            return;
        }
        if (channel === 'stderr') {
            run.stderrBuffer += content;
            const filtered = filterCompleteStderrLines(run.stderrBuffer);
            run.stderrBuffer = filtered.remainder;
            if (filtered.content.length === 0) return;
            this.recordStderr(run, filtered.content);
            return;
        }
        this.recordOutput(runId, channel, content);
    }

    recordStderr(run, content) {
        const parts = content.split(/(\r\n|\r|\n)/u);
        for (let index = 0; index < parts.length; index += 2) {
            const line = stripAnsi(parts[index]);
            const delimiter = parts[index + 1] ?? '';
            if (line.length === 0 && delimiter.length === 0) continue;
            if (run.agent !== 'codex' || !isCodexCacheError(line)) {
                this.recordOutput(run.id, 'stderr', `${line}${delimiter}`);
                continue;
            }
            if (run.codexCacheErrorReported) continue;
            run.codexCacheErrorReported = true;
            const diagnostic = run.stderrHandling.then(async () => {
                const result = await this.diagnoseCodexCacheError(line, run.executable, run.environment);
                this.recordOutput(run.id, 'stderr', `${result.message}\n`);
                if (result.updateRequired) {
                    this.codexRuntimeService?.publishUpdateRequired(result.runningVersion, result.cacheVersion);
                }
            });
            run.stderrHandling = diagnostic.catch(() => {
                this.recordOutput(run.id, 'stderr', `${line}${delimiter}`);
            });
        }
    }

    handleStreamingLine(runId, line) {
        const run = this.processes.get(runId);
        if (!run) return;

        let message;
        try {
            message = JSON.parse(line);
        } catch {
            this.handleMalformedOutput(runId, line);
            return;
        }
        run.protocolHandling = run.protocolHandling
            .then(() => run.streamingAdapter.handleMessage(message))
            .catch((error) => {
                this.failStreamingRun(run, error);
            });
    }

    recordOutput(runId, channel, content) {
        const run = this.processes.get(runId);
        if (!run) return;

        const timestamp = new Date().toISOString();
        const safeContent = redactSecrets(content, run.secretValues);
        if (channel === 'stdout') {
            const { segment } = appendAssistantOutput(run, safeContent, timestamp);
            if (segment.length === 0) return;
            emitRunEvent(run, { content: segment, type: 'output' });
            return;
        }
        run.stderr += safeContent;
        if (run.streaming) {
            emitRunEvent(run, { content: safeContent, type: 'error' });
            return;
        }
        run.conversation.entries.push(createEventEntry(
            `${runId}-error-${run.conversation.entries.length}`,
            'error',
            safeContent,
            timestamp,
            nextRunSequence(run),
        ));
        emitRunEvent(run, { content: safeContent, type: 'error' });
    }

    flushStderr(runId) {
        const run = this.processes.get(runId);
        if (!run || run.stderrBuffer.length === 0) return;

        const content = run.stderrBuffer;
        run.stderrBuffer = '';
        if (!isHiddenStderrLine(content)) this.recordStderr(run, content);
    }

    handleProviderEvent(runId, providerEvent) {
        const run = this.processes.get(runId);
        if (!run) return;

        const timestamp = new Date().toISOString();
        run.turnStarted = run.turnStarted || providerEvent.turnStarted;
        run.missingSession = run.missingSession || providerEvent.missingSession;
        providerEvent.changedPaths.forEach((filePath) => run.changedPaths.add(filePath));
        if (providerEvent.conversationId) run.providerConversationId = providerEvent.conversationId;
        if (providerEvent.usage) run.turnUsage = providerEvent.usage;
        for (const transcriptEvent of providerEvent.transcriptEvents) {
            run.conversation.entries.push(createEventEntry(
                `${runId}-provider-${run.conversation.entries.length}`,
                transcriptEvent.toolType,
                transcriptEvent.content,
                timestamp,
                nextRunSequence(run),
            ));
        }
        if (providerEvent.assistantText.length > 0) {
            const { segment } = appendAssistantOutput(run, providerEvent.assistantText, timestamp);
            if (segment.length > 0) emitRunEvent(run, { content: segment, type: 'output' });
        } else if (providerEvent.errorText.length > 0 && !run.reportedProviderErrors.has(providerEvent.errorText)) {
            const separator = run.stderr.length > 0 && !run.stderr.endsWith('\n') ? '\n' : '';
            run.reportedProviderErrors.add(providerEvent.errorText);
            run.stderr += `${separator}${providerEvent.errorText}`;
            run.conversation.entries.push(createEventEntry(
                `${runId}-error-${run.conversation.entries.length}`,
                'error',
                providerEvent.errorText,
                timestamp,
                nextRunSequence(run),
            ));
            emitRunEvent(run, { content: providerEvent.errorText, type: 'error' });
        }
    }

    async handleStreamingEvent(runId, event) {
        const run = this.processes.get(runId);
        if (!run) return;

        const handler = STREAMING_EVENT_HANDLERS[event.type];
        if (!handler) return;

        await handler(this, run, event, new Date().toISOString());
    }

    handleMalformedOutput(runId, line) {
        const run = this.processes.get(runId);
        if (!run) return;

        if (!run.streaming) {
            const timestamp = new Date().toISOString();
            const message = `Malformed ${run.agent} JSONL event: ${line}`;
            run.conversation.entries.push(createEventEntry(
                `${runId}-malformed-${run.conversation.entries.length}`,
                'diagnostic',
                message,
                timestamp,
                nextRunSequence(run),
            ));
            return;
        }
        this.failStreamingRun(run, new Error(`Malformed ${run.agent} JSONL event`));
    }

    handleError(runId, error) {
        const run = this.processes.get(runId);
        if (!run) return;

        if (run.streaming) {
            this.failStreamingRun(run, error);
            return;
        }
        const timestamp = new Date().toISOString();
        const message = error instanceof Error ? error.message : 'Agent process failed';
        run.stderr += message;
        run.conversation.entries.push(createEventEntry(
            `${runId}-error-${run.conversation.entries.length}`,
            'error',
            message,
            timestamp,
            nextRunSequence(run),
        ));
        emitRunEvent(run, { content: message, type: 'error' });
    }

    failStreamingRun(run, errorValue) {
        if (run.streamingFailure) return run.termination;

        const error = errorValue instanceof Error ? errorValue : new Error('Streaming agent failed');
        const message = redactSecrets(error.message, run.secretValues);
        const timestamp = new Date().toISOString();
        run.streamingFailure = new Error(message);
        transitionConversationStatus(run.conversation, 'failed', timestamp);
        run.queuedMessage = null;
        run.waitingForQuestion = false;
        run.pendingQuestions = [];
        const separator = run.stderr.length > 0 && !run.stderr.endsWith('\n') ? '\n' : '';
        run.stderr += `${separator}${message}`;
        run.conversation.entries.push(createEventEntry(
            `${run.id}-error-${run.conversation.entries.length}`,
            'error',
            message,
            timestamp,
            nextRunSequence(run),
        ));
        emitRunEvent(run, { content: message, type: 'error' });
        emitRunEvent(run, { state: 'failed', type: 'state' });
        try {
            run.child.stdin.end();
        } catch {
            // Process-tree termination below remains authoritative.
        }

        return this.ensureTermination(run);
    }

    async handleClose(runId, exitCode) {
        const run = this.processes.get(runId);
        if (!run) return;
        this.clearFinishTimeout(run);

        try {
            if (run.termination) await run.termination;
            run.parser?.finish();
            run.protocolLines?.finish();
            await run.protocolHandling;
            this.flushStderr(runId);
            await run.stderrHandling;
            const completedAt = new Date().toISOString();
            if (run.streaming && !run.finishing && !run.cancelled && !run.streamingFailure && !run.suspended) {
                run.streamingFailure = new Error('Streaming agent process exited before Finish');
                const separator = run.stderr.length > 0 && !run.stderr.endsWith('\n') ? '\n' : '';
                run.stderr += `${separator}${run.streamingFailure.message}`;
            }
            const succeeded = (exitCode === 0 || (run.finishing && run.finishForced))
                && !run.missingSession
                && !run.cancelled
                && !run.streamingFailure
                && (!run.streaming || run.finishing);
            completeAssistantOutput(run, completedAt);
            if (succeeded) {
                const synchronizedMessage = lastMessageEntry(run.conversation);
                updateProviderSession(run, synchronizedMessage.id, completedAt);
                if (run.turnUsage) run.conversation.usage = accumulateUsage(run.conversation.usage, run.turnUsage);
                if (!run.streaming && run.turnUsage) await this.recordTokenUsage(run, run.turnUsage, completedAt);
            }
            const preserveWaitingState = run.suspended && run.conversation.status === 'waitingForInput';
            run.conversation.completedAt = preserveWaitingState ? null : completedAt;
            const status = preserveWaitingState
                ? 'waitingForInput'
                : run.cancelled ? 'cancelled' : succeeded ? 'completed' : 'failed';
            transitionConversationStatus(run.conversation, status, completedAt);
            const continuedTurnFailedBeforeStart = !!run.request.conversation
                && !run.turnStarted
                && !succeeded
                && !run.cancelled
                && !run.suspended;
            logAgentEvent('[agent:complete]', {
                completedAt,
                durationMs: Date.parse(completedAt) - Date.parse(run.startedAt),
                actionRunId: run.request.actionRunId ?? null,
                exitCode,
                pid: run.child.pid,
                runId,
            });
            await run.persistence;
            if (!continuedTurnFailedBeforeStart) await this.persistConversation(run);
            this.processes.delete(runId);
            this.runningConversationIds.delete(run.conversation.id);
            emitRunEvent(run, { conversation: run.conversation, type: 'closed' });
            this.requestClaudeUsagePoll(run);
            if (run.onComplete) run.onComplete(succeeded ? 0 : exitCode || 1, run);
        } catch (error) {
            if (run.onCompletionError) run.onCompletionError(error);
        } finally {
            this.processes.delete(runId);
            this.runningConversationIds.delete(run.conversation.id);
        }
    }

    requireRun(runId) {
        const run = this.processes.get(runId);
        if (!run) throw new Error(`Agent run is not active: ${runId}`);

        return run;
    }

    persistCheckpoint(run) {
        const snapshot = { ...run, conversation: snapshotConversation(run.conversation) };
        const write = run.persistence.then(() => this.persistConversationCheckpoint(snapshot));
        run.persistence = write.catch(() => undefined);

        return write;
    }

    requireStreamingRun(runId) {
        const run = this.requireRun(runId);
        if (!run.streaming) throw new Error(`Agent run is not streaming: ${runId}`);

        return run;
    }
}

module.exports = { AGENT_FINISH_GRACE_MS, AgentRunnerService };

const {
    accumulateUsage,
    createProviderEventEntry,
    createEventEntry,
    transitionConversationStatus,
    updateProviderSession,
} = require('./agent_conversation');
const { emitRunEvent, hasPendingInteraction } = require('./agent_run_state');
const {
    appendAssistantOutput,
    appendDiagnosticContent,
    completeAssistantOutput,
    lastMessageEntry,
    nextRunSequence,
    replaceAssistantOutput,
    startAssistantItem,
} = require('./agent_run_transcript');
const { redactConversationEvent, redactSecrets } = require('./agent_secret_redaction');
const { requireString } = require('./agent_run_validation');

function handleSessionStarted(service, run, event) {
    run.providerConversationId = event.conversationId;
}

function handleTurnStarted(service, run) {
    run.assistantItemIndex = 0;
    run.assistantItems.clear();
    run.currentAssistantMessageId = null;
    run.liveTurnUsage = null;
    run.turnStarted = true;
}

function handleUsage(service, run, event) {
    run.liveTurnUsage = event.usage;
    const usage = accumulateUsage(run.conversation.usage, event.usage);
    emitRunEvent(run, {
        ...(event.contextWindowUsage !== undefined ? { contextWindowUsage: event.contextWindowUsage } : {}),
        type: 'usage',
        usage,
    });
}

function handleAssistantStarted(service, run, event, timestamp) {
    const item = startAssistantItem(run, requireString(event.itemId, 'assistant item id'), timestamp);
    emitRunEvent(run, { content: '', messageId: item.messageId, sequence: item.sequence, type: 'output' });
}

function handleAssistant(service, run, event, timestamp) {
    const safeContent = redactSecrets(event.content, run.secretValues);
    const itemId = run.agent === 'codex'
        ? requireString(event.itemId, 'assistant item id')
        : event.itemId;
    const { message, segment } = appendAssistantOutput(run, safeContent, timestamp, itemId);
    if (segment.length > 0) {
        emitRunEvent(run, { content: segment, messageId: message.id, sequence: message.sequence, type: 'output' });
    }
}

function handleAssistantCompleted(service, run, event, timestamp) {
    const safeContent = redactSecrets(event.content, run.secretValues);
    const itemId = requireString(event.itemId, 'assistant item id');
    const { message, previousContent, replaced } = replaceAssistantOutput(run, safeContent, timestamp, itemId);
    if (!replaced) return;

    emitRunEvent(run, {
        content: safeContent,
        messageId: message.id,
        previousContent,
        replace: true,
        sequence: message.sequence,
        type: 'output',
    });
}

function handleChangedPaths(service, run, event) {
    event.paths.forEach((filePath) => run.changedPaths.add(filePath));
}

/** Provider events are keyed by `providerItemId` so a later revision of the same item replaces its entry. */
function handleEvent(service, run, event, timestamp) {
    const safeEvent = redactConversationEvent(event.event, run.secretValues);
    const providerItemId = requireString(safeEvent.providerItemId, 'event providerItemId');
    const currentIndex = run.providerEventEntryIndexes.get(providerItemId);
    let eventEntry;
    if (currentIndex !== undefined) {
        const current = run.conversation.entries[currentIndex];
        eventEntry = createProviderEventEntry(safeEvent, current.id, timestamp, current.sequence);
        run.conversation.entries[currentIndex] = eventEntry;
    } else {
        const previousEntry = run.conversation.entries.at(-1);
        if (safeEvent.type === 'diagnostic' && previousEntry?.kind === 'event' && previousEntry.type === 'diagnostic') {
            eventEntry = appendDiagnosticContent(previousEntry, safeEvent.content);
            run.conversation.entries[run.conversation.entries.length - 1] = eventEntry;
        } else {
            const sequence = nextRunSequence(run);
            eventEntry = createProviderEventEntry(
                safeEvent,
                `${run.id}-event-${sequence}`,
                timestamp,
                sequence,
            );
            run.providerEventEntryIndexes.set(providerItemId, run.conversation.entries.length);
            run.conversation.entries.push(eventEntry);
        }
    }
    emitRunEvent(run, { event: eventEntry, type: 'agentEvent' });
}

function handleTranscript(service, run, event, timestamp) {
    const safeContent = redactSecrets(event.content, run.secretValues);
    run.conversation.entries.push(createEventEntry(
        `${run.id}-provider-${run.conversation.entries.length}`,
        event.toolType,
        safeContent,
        timestamp,
        nextRunSequence(run),
    ));
}

function handleError(service, run, event) {
    service.recordOutput(run.id, 'stderr', event.content);
}

function handleFatal(service, run, event) {
    service.failStreamingRun(run, new Error(event.content));
}

function handleSessionFailed(service, run, event) {
    run.missingSession = event.missingSession;
    service.failStreamingRun(run, new Error(event.content));
}

async function handleQuestion(service, run, event, timestamp) {
    transitionConversationStatus(run.conversation, 'waitingForInput', timestamp);
    run.waitingForQuestion = true;
    run.pendingQuestions = event.questions;
    await service.persistCheckpoint(run);
    emitRunEvent(run, { state: 'waitingForInput', type: 'state' });
    emitRunEvent(run, { questions: event.questions, requestId: event.requestId, state: 'waitingForInput', type: 'question' });
}

async function handleApproval(service, run, event, timestamp) {
    const requestId = event.approval.requestId;
    if (run.pendingApprovals.has(requestId)) throw new Error(`Duplicate agent approval request id: ${requestId}`);
    run.pendingApprovals.set(requestId, { ...event.approval, submitted: false });
    transitionConversationStatus(run.conversation, 'waitingForInput', timestamp);
    await service.persistCheckpoint(run);
    emitRunEvent(run, { state: 'waitingForInput', type: 'state' });
    emitRunEvent(run, { approval: event.approval, state: 'waitingForInput', type: 'approval' });
}

function handleApprovalSubmitted(service, run, event) {
    const approval = run.pendingApprovals.get(event.requestId);
    if (!approval) return;
    approval.submitted = true;
    emitRunEvent(run, { requestId: event.requestId, type: 'approvalSubmitted' });
}

async function handleApprovalResolved(service, run, event, timestamp) {
    if (!run.pendingApprovals.delete(event.requestId)) return;
    const state = hasPendingInteraction(run) ? 'waitingForInput' : 'running';
    transitionConversationStatus(run.conversation, state, timestamp);
    await service.persistCheckpoint(run);
    emitRunEvent(run, { requestId: event.requestId, state, type: 'approvalResolved' });
    emitRunEvent(run, { state, type: 'state' });
}

/**
 * End of a streaming turn: settle the assistant message, then either shut the process down,
 * send the message queued while the turn was running, or park the run waiting for input.
 */
async function handleTurnCompleted(service, run, event, timestamp) {
    completeAssistantOutput(run, timestamp);
    run.turnActive = false;
    run.waitingForQuestion = false;
    run.pendingApprovals.clear();
    run.missingSession = run.missingSession || event.missingSession;
    if (event.missingSession) run.finishing = true;
    if (event.usage) {
        run.liveTurnUsage = event.usage;
        run.conversation.usage = accumulateUsage(run.conversation.usage, run.liveTurnUsage);
        run.liveTurnUsage = null;
    }
    if (event.contextWindowUsage !== undefined) {
        if (event.contextWindowUsage) run.conversation.contextWindowUsage = event.contextWindowUsage;
        else delete run.conversation.contextWindowUsage;
    }
    if (event.usage || event.contextWindowUsage !== undefined) {
        emitRunEvent(run, {
            ...(event.contextWindowUsage !== undefined ? { contextWindowUsage: event.contextWindowUsage } : {}),
            type: 'usage',
            usage: run.conversation.usage,
        });
    }
    if (event.error) {
        service.failStreamingRun(run, new Error(event.error));
        return;
    }
    if (!event.missingSession && event.usage) await service.recordTokenUsage(run, event.usage, timestamp);
    if (run.finishing) {
        service.beginFinishShutdown(run);
        return;
    }
    if (run.queuedMessage) {
        const { content, revision } = run.queuedMessage;
        transitionConversationStatus(run.conversation, 'waitingForInput', timestamp);
        await service.sendStreamingMessage(run, content);
        run.queuedMessage = null;
        run.sentQueuedMessageRevision = revision;
        return;
    }
    const synchronizedMessage = lastMessageEntry(run.conversation);
    if (synchronizedMessage) updateProviderSession(run, synchronizedMessage.id, timestamp);
    transitionConversationStatus(run.conversation, 'waitingForInput', timestamp);
    run.conversation.completedAt = null;
    await service.persistCheckpoint(run);
    emitRunEvent(run, { state: 'waitingForInput', type: 'state' });
}

/** Keyed by streaming event type; unknown types are ignored. Each handler takes `(service, run, event, timestamp)`. */
const STREAMING_EVENT_HANDLERS = {
    approval: handleApproval,
    approvalResolved: handleApprovalResolved,
    approvalSubmitted: handleApprovalSubmitted,
    assistant: handleAssistant,
    assistantCompleted: handleAssistantCompleted,
    assistantStarted: handleAssistantStarted,
    changedPaths: handleChangedPaths,
    error: handleError,
    event: handleEvent,
    fatal: handleFatal,
    question: handleQuestion,
    sessionFailed: handleSessionFailed,
    sessionStarted: handleSessionStarted,
    transcript: handleTranscript,
    turnCompleted: handleTurnCompleted,
    turnStarted: handleTurnStarted,
    usage: handleUsage,
};

module.exports = { STREAMING_EVENT_HANDLERS };

import { parseAgentConversation } from './agent_conversations.mjs'

const ACTIVITY_VERSION = 4
export const LEGACY_ACTIVITY_VERSION = 1
export const SECOND_ACTIVITY_VERSION = 2
export const PREVIOUS_ACTIVITY_VERSION = 3
const ACTION_ACTIVITY_STATUSES = new Set(['cancelled', 'completed', 'failed', 'okButNotAfter'])

function requiredString(value, fieldName, allowEmpty = false) {
    if (typeof value !== 'string' || (!allowEmpty && value.length === 0)) throw new Error(`Malformed activity file: missing ${fieldName}`)

    return value
}

function requiredTimestamp(value, fieldName) {
    const timestamp = requiredString(value, fieldName)
    if (Number.isNaN(Date.parse(timestamp))) throw new Error(`Malformed activity file: invalid ${fieldName}`)

    return timestamp
}

function nonNegativeInteger(value, fieldName) {
    if (!Number.isInteger(value) || value < 0) throw new Error(`Malformed activity file: invalid ${fieldName}`)

    return value
}

function requiredStringArray(value, fieldName) {
    if (!Array.isArray(value)) throw new Error(`Malformed activity file: invalid ${fieldName}`)

    return value.map((entry, index) => requiredString(entry, `${fieldName}[${index}]`))
}

function parseOrigin(value) {
    if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error('Malformed activity file: missing origin')
    if (value.kind === 'project') return { kind: 'project' }
    if (value.kind !== 'card') throw new Error(`Malformed activity file: invalid origin kind ${String(value.kind)}`)

    return { cardInternalId: requiredString(value.cardInternalId, 'origin.cardInternalId'), kind: 'card' }
}

function parseActionSettings(value) {
    if (!value || typeof value !== 'object' || Array.isArray(value)) {
        throw new Error('Malformed activity file: actionSettings must be an object')
    }

    return Object.fromEntries(Object.entries(value).map(([actionId, settings]) => {
        if (actionId.length === 0) throw new Error('Malformed activity file: actionSettings action ID must not be empty')
        if (!settings || typeof settings !== 'object' || Array.isArray(settings)) {
            throw new Error(`Malformed activity file: invalid actionSettings.${actionId}`)
        }

        if (settings.accessLevel !== undefined || settings.approvalPolicy !== undefined) {
            throw new Error(`Malformed activity file: obsolete permission fields in actionSettings.${actionId}`)
        }

        return [actionId, {
            agent: requiredString(settings.agent, `actionSettings.${actionId}.agent`, true),
            model: requiredString(settings.model, `actionSettings.${actionId}.model`, true),
            permissionMode: requiredString(settings.permissionMode, `actionSettings.${actionId}.permissionMode`, true),
            thinkingLevel: requiredString(settings.thinkingLevel, `actionSettings.${actionId}.thinkingLevel`, true),
        }]
    }))
}

function sameOrigin(first, second) {
    return first.kind === second.kind && first.cardInternalId === second.cardInternalId
}

function parseCommit(value, index) {
    if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error(`Malformed activity file: invalid commits[${index}]`)
    const commit = {
        branch: requiredString(value.branch, `commits[${index}].branch`),
        commit: requiredString(value.commit, `commits[${index}].commit`),
        committedAt: requiredTimestamp(value.committedAt, `commits[${index}].committedAt`),
        deletions: nonNegativeInteger(value.deletions, `commits[${index}].deletions`),
        filePaths: requiredStringArray(value.filePaths, `commits[${index}].filePaths`),
        filesChanged: nonNegativeInteger(value.filesChanged, `commits[${index}].filesChanged`),
        insertions: nonNegativeInteger(value.insertions, `commits[${index}].insertions`),
    }
    if (!/^[0-9a-f]{40}$/iu.test(commit.commit)) throw new Error(`Malformed activity file: invalid commits[${index}].commit`)
    if (value.available !== undefined) {
        if (typeof value.available !== 'boolean') throw new Error(`Malformed activity file: invalid commits[${index}].available`)
        commit.available = value.available
    }
    if (value.actionId !== undefined || value.actionName !== undefined) {
        commit.actionId = requiredString(value.actionId, `commits[${index}].actionId`)
        commit.actionName = requiredString(value.actionName, `commits[${index}].actionName`)
    }

    return commit
}

function parseLegacyHistory(value, index) {
    if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error(`Malformed activity file: invalid records[${index}].history`)
    const status = requiredString(value.status, `records[${index}].history.status`)
    if (status !== 'completed' && status !== 'failed') throw new Error(`Malformed activity file: invalid records[${index}].history.status`)
    const history = {
        completedAt: requiredTimestamp(value.completedAt, `records[${index}].history.completedAt`),
        output: requiredString(value.output, `records[${index}].history.output`, true),
        prompt: requiredString(value.prompt, `records[${index}].history.prompt`, true),
        status,
    }
    for (const fieldName of ['accessLevel', 'agent', 'approvalPolicy', 'command', 'model', 'thinkingLevel']) {
        if (value[fieldName] === undefined) continue
        if (fieldName === 'agent' && value[fieldName] === null) history[fieldName] = null
        else history[fieldName] = requiredString(value[fieldName], `records[${index}].history.${fieldName}`)
    }

    return history
}

function parseAgentDetails(value, index) {
    if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error(`Malformed activity file: invalid records[${index}].details`)
    const details = { type: 'agent' }
    if (value.accessLevel !== undefined || value.approvalPolicy !== undefined) {
        throw new Error(`Malformed activity file: obsolete permission fields in records[${index}].details`)
    }
    for (const fieldName of ['agent', 'model', 'permissionMode', 'thinkingLevel']) {
        if (value[fieldName] === undefined) continue
        if (fieldName === 'agent' && value[fieldName] === null) details[fieldName] = null
        else details[fieldName] = requiredString(value[fieldName], `records[${index}].details.${fieldName}`)
    }

    return details
}

function parseCommandDetails(value, index) {
    if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error(`Malformed activity file: invalid records[${index}].details`)

    return {
        command: requiredString(value.command, `records[${index}].details.command`, true),
        output: requiredString(value.output, `records[${index}].details.output`, true),
        type: 'command',
    }
}

function parseDetails(value, index) {
    if (value?.type === 'agent') return parseAgentDetails(value, index)
    if (value?.type === 'command') return parseCommandDetails(value, index)

    throw new Error(`Malformed activity file: invalid records[${index}].details.type`)
}

function parseSystemRecord(value, index, activityOrigin) {
    if (!Array.isArray(value.commits) || value.commits.length !== 1) {
        throw new Error(`Malformed activity file: system records[${index}].commits must contain one commit`)
    }
    const origin = parseOrigin(value.origin)
    if (!sameOrigin(origin, activityOrigin)) throw new Error(`Malformed activity file: records[${index}].origin does not match activity origin`)

    return {
        commits: value.commits.map(parseCommit),
        completedAt: requiredTimestamp(value.completedAt, `records[${index}].completedAt`),
        label: requiredString(value.label, `records[${index}].label`),
        origin,
        type: 'system',
    }
}

function parseRecord(value, index, activityOrigin) {
    if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error(`Malformed activity file: invalid records[${index}]`)
    if (value.type === 'system') return parseSystemRecord(value, index, activityOrigin)
    const status = requiredString(value.status, `records[${index}].status`)
    if (!ACTION_ACTIVITY_STATUSES.has(status)) throw new Error(`Malformed activity file: invalid records[${index}].status`)
    if (!Array.isArray(value.commits)) throw new Error(`Malformed activity file: invalid records[${index}].commits`)
    if (!Array.isArray(value.conversationIds)) throw new Error(`Malformed activity file: invalid records[${index}].conversationIds`)

    const origin = parseOrigin(value.origin)
    if (!sameOrigin(origin, activityOrigin)) throw new Error(`Malformed activity file: records[${index}].origin does not match activity origin`)

    if (value.history !== undefined) throw new Error(`Malformed activity file: records[${index}].history is not supported`)
    const details = parseDetails(value.details, index)
    if (details.type === 'command' && value.rootConversationId !== undefined) {
        throw new Error(`Malformed activity file: command records[${index}] cannot have rootConversationId`)
    }
    const record = {
        commits: value.commits.map(parseCommit),
        completedAt: requiredTimestamp(value.completedAt, `records[${index}].completedAt`),
        conversationIds: requiredStringArray(value.conversationIds, `records[${index}].conversationIds`),
        details,
        runId: requiredString(value.runId, `records[${index}].runId`),
        origin,
        rootActionId: requiredString(value.rootActionId, `records[${index}].rootActionId`),
        rootActionLabel: requiredString(value.rootActionLabel, `records[${index}].rootActionLabel`),
        startedAt: requiredTimestamp(value.startedAt, `records[${index}].startedAt`),
        status,
    }
    if (details.type === 'agent') record.rootConversationId = requiredString(value.rootConversationId, `records[${index}].rootConversationId`)

    return record
}

function parseLegacyRecord(value, index, activityOrigin) {
    if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error(`Malformed activity file: invalid records[${index}]`)
    if (value.type === 'system') return parseSystemRecord(value, index, activityOrigin)
    const status = requiredString(value.status, `records[${index}].status`)
    if (!ACTION_ACTIVITY_STATUSES.has(status)) throw new Error(`Malformed activity file: invalid records[${index}].status`)
    if (!Array.isArray(value.commits)) throw new Error(`Malformed activity file: invalid records[${index}].commits`)
    const origin = parseOrigin(value.origin)
    if (!sameOrigin(origin, activityOrigin)) throw new Error(`Malformed activity file: records[${index}].origin does not match activity origin`)

    return {
        commits: value.commits.map(parseCommit),
        completedAt: requiredTimestamp(value.completedAt, `records[${index}].completedAt`),
        conversationIds: requiredStringArray(value.conversationIds, `records[${index}].conversationIds`),
        history: parseLegacyHistory(value.history, index),
        origin,
        rootActionId: requiredString(value.rootActionId, `records[${index}].rootActionId`),
        rootActionLabel: requiredString(value.rootActionLabel, `records[${index}].rootActionLabel`),
        runId: requiredString(value.runId, `records[${index}].runId`),
        startedAt: requiredTimestamp(value.startedAt, `records[${index}].startedAt`),
        status,
    }
}

function parseConversation(value, index, activityOrigin) {
    try {
        const parsed = parseAgentConversation(JSON.stringify(value), '')
        const expectedCardInternalId = activityOrigin.kind === 'card' ? activityOrigin.cardInternalId : null
        if (parsed.cardInternalId !== expectedCardInternalId) throw new Error('conversation cardInternalId does not match activity origin')

        return Object.fromEntries(Object.entries(parsed).filter(([fieldName]) => fieldName !== 'path'))
    } catch (error) {
        const detail = error instanceof Error ? error.message : 'invalid conversation'
        throw new Error(`Malformed activity file: conversations[${index}] ${detail}`, { cause: error })
    }
}

function repairConversation(value, index, activityOrigin) {
    if (!value || typeof value !== 'object' || Array.isArray(value)) return null
    const entries = Array.isArray(value.entries) ? value.entries.filter((entry) => {
        try {
            parseAgentConversation(JSON.stringify({ ...value, entries: [entry] }), '')

            return true
        } catch {
            return false
        }
    }) : []

    try {
        return parseConversation({ ...value, entries }, index, activityOrigin)
    } catch {
        return null
    }
}

export function createActivityFile(origin) {
    return { actionSettings: {}, conversations: [], origin: parseOrigin(origin), records: [], version: ACTIVITY_VERSION }
}

export function parseActivityValue(value, expectedOrigin = null) {
    if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error('Malformed activity file: root must be an object')
    if (value.version !== ACTIVITY_VERSION) throw new Error(`Malformed activity file: unsupported version ${String(value.version)}`)
    if (!Array.isArray(value.records)) throw new Error('Malformed activity file: records must be an array')
    if (!Array.isArray(value.conversations)) throw new Error('Malformed activity file: conversations must be an array')
    const actionSettings = parseActionSettings(value.actionSettings)
    const origin = parseOrigin(value.origin)
    if (expectedOrigin) {
        const expected = parseOrigin(expectedOrigin)
        if (!sameOrigin(origin, expected)) {
            throw new Error('Malformed activity file: origin does not match requested activity')
        }
    }

    const conversations = value.conversations.map((conversation, index) => parseConversation(conversation, index, origin))
    const records = value.records.map((record, index) => parseRecord(record, index, origin))
    for (const [index, record] of records.entries()) {
        if (record.type === 'system' || record.details.type !== 'agent') continue
        if (!record.conversationIds.includes(record.rootConversationId)) {
            throw new Error(`Malformed activity file: records[${index}].rootConversationId is not in conversationIds`)
        }
        const conversation = conversations.find(({ id }) => id === record.rootConversationId)
        if (!conversation) throw new Error(`Malformed activity file: records[${index}].rootConversationId does not resolve`)
        if (conversation.actionId !== record.rootActionId) {
            throw new Error(`Malformed activity file: records[${index}].rootConversationId action does not match rootActionId`)
        }
    }

    return {
        actionSettings,
        conversations,
        origin,
        records,
        version: ACTIVITY_VERSION,
    }
}

function legacyPermissionMode(agent, accessLevel, approvalPolicy, fieldName) {
    if (accessLevel === undefined && approvalPolicy === undefined) return undefined
    if (agent === 'codex' && accessLevel === 'workspace-write' && approvalPolicy === 'on-request') return 'ask-for-approval'
    if (agent === 'codex' && accessLevel === 'danger-full-access' && approvalPolicy === 'never') return 'full-access'
    if (agent === 'claude' && (accessLevel === undefined || accessLevel === '')) {
        if (approvalPolicy === 'acceptEdits') return 'ask-for-approval'
        if (approvalPolicy === 'auto') return 'approve-for-me'
        if (approvalPolicy === 'bypassPermissions') return 'full-access'
    }

    throw new Error(`Cannot migrate activity file: unrecognised legacy permission combination in ${fieldName}`)
}

function migrateVersionThreeActionSettings(value) {
    if (!value || typeof value !== 'object' || Array.isArray(value)) {
        throw new Error('Malformed activity file: actionSettings must be an object')
    }

    return Object.fromEntries(Object.entries(value).map(([actionId, settings]) => {
        if (!settings || typeof settings !== 'object' || Array.isArray(settings)) {
            throw new Error(`Malformed activity file: invalid actionSettings.${actionId}`)
        }
        const permissionMode = legacyPermissionMode(
            settings.agent,
            settings.accessLevel,
            settings.approvalPolicy,
            `actionSettings.${actionId}`,
        )

        return [actionId, {
            agent: requiredString(settings.agent, `actionSettings.${actionId}.agent`, true),
            model: requiredString(settings.model, `actionSettings.${actionId}.model`, true),
            ...(permissionMode !== undefined ? { permissionMode } : { permissionMode: '' }),
            thinkingLevel: requiredString(settings.thinkingLevel, `actionSettings.${actionId}.thinkingLevel`, true),
        }]
    }))
}

function migrateLegacyRecord(record, index, conversations) {
    if (record.type === 'system') return record
    const { history, ...base } = record
    const agentRecord = history.agent !== undefined
        || history.accessLevel !== undefined
        || history.approvalPolicy !== undefined
        || history.model !== undefined
        || history.thinkingLevel !== undefined
    if (!agentRecord) {
        return {
            ...base,
            details: { command: history.command ?? '', output: history.output, type: 'command' },
        }
    }

    const candidates = conversations.filter((conversation) => (
        record.conversationIds.includes(conversation.id) && conversation.actionId === record.rootActionId
    ))
    if (candidates.length !== 1) {
        throw new Error(`Cannot migrate activity file: agent records[${index}] has ${candidates.length} matching root conversations`)
    }
    const permissionMode = legacyPermissionMode(
        history.agent,
        history.accessLevel,
        history.approvalPolicy,
        `records[${index}].history`,
    )
    const details = Object.fromEntries(Object.entries({
        agent: history.agent,
        model: history.model,
        permissionMode,
        thinkingLevel: history.thinkingLevel,
        type: 'agent',
    }).filter(([, fieldValue]) => fieldValue !== undefined))

    return { ...base, details, rootConversationId: candidates[0].id }
}

function migrateVersionThreeRecord(record, index) {
    if (record.type === 'system' || record.details?.type !== 'agent') return record
    const { accessLevel, approvalPolicy, ...details } = record.details
    const permissionMode = legacyPermissionMode(details.agent, accessLevel, approvalPolicy, `records[${index}].details`)

    return {
        ...record,
        details: { ...details, ...(permissionMode !== undefined ? { permissionMode } : {}) },
    }
}

export function migrateActivityValue(value, expectedOrigin = null) {
    if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error('Malformed activity file: root must be an object')
    if (![LEGACY_ACTIVITY_VERSION, SECOND_ACTIVITY_VERSION, PREVIOUS_ACTIVITY_VERSION].includes(value.version)) {
        throw new Error(`Cannot migrate activity file version ${String(value.version)}`)
    }
    if (value.version === PREVIOUS_ACTIVITY_VERSION || value.version === SECOND_ACTIVITY_VERSION) {
        const actionSettings = value.version === PREVIOUS_ACTIVITY_VERSION
            ? migrateVersionThreeActionSettings(value.actionSettings)
            : {}
        const records = value.records.map(migrateVersionThreeRecord)

        return parseActivityValue({ ...value, actionSettings, records, version: ACTIVITY_VERSION }, expectedOrigin)
    }
    if (!Array.isArray(value.records)) throw new Error('Malformed activity file: records must be an array')
    if (!Array.isArray(value.conversations)) throw new Error('Malformed activity file: conversations must be an array')
    const origin = parseOrigin(value.origin)
    if (expectedOrigin && !sameOrigin(origin, parseOrigin(expectedOrigin))) {
        throw new Error('Malformed activity file: origin does not match requested activity')
    }
    const conversations = value.conversations.map((conversation, index) => parseConversation(conversation, index, origin))
    const legacyRecords = value.records.map((record, index) => parseLegacyRecord(record, index, origin))
    const migrated = {
        actionSettings: {},
        conversations,
        origin,
        records: legacyRecords.map((record, index) => migrateLegacyRecord(record, index, conversations)),
        version: ACTIVITY_VERSION,
    }

    return parseActivityValue(migrated, expectedOrigin)
}

function repairActionSettings(value, version) {
    if (version === LEGACY_ACTIVITY_VERSION || version === SECOND_ACTIVITY_VERSION) return {}
    if (!value || typeof value !== 'object' || Array.isArray(value)) return {}

    return Object.fromEntries(Object.entries(value).flatMap(([actionId, settings]) => {
        try {
            const parsed = version === PREVIOUS_ACTIVITY_VERSION
                ? migrateVersionThreeActionSettings({ [actionId]: settings })
                : parseActionSettings({ [actionId]: settings })

            return [[actionId, parsed[actionId]]]
        } catch {
            return []
        }
    }))
}

function repairRecordCollections(value) {
    if (!value || typeof value !== 'object' || Array.isArray(value)) return value
    const commits = Array.isArray(value.commits) ? value.commits.flatMap((commit, index) => {
        try {
            return [parseCommit(commit, index)]
        } catch {
            return []
        }
    }) : []
    const conversationIds = Array.isArray(value.conversationIds)
        ? value.conversationIds.filter((conversationId) => typeof conversationId === 'string' && conversationId.length > 0)
        : []

    return { ...value, commits, conversationIds }
}

function repairRecord(value, index, version, origin, conversations) {
    const normalizedValue = repairRecordCollections(value)
    try {
        if (version === LEGACY_ACTIVITY_VERSION) {
            const legacyRecord = parseLegacyRecord(normalizedValue, index, origin)
            const migratedRecord = migrateLegacyRecord(legacyRecord, index, conversations)

            return parseRecord(migratedRecord, index, origin)
        }
        const migratedRecord = version === SECOND_ACTIVITY_VERSION || version === PREVIOUS_ACTIVITY_VERSION
            ? migrateVersionThreeRecord(normalizedValue, index)
            : normalizedValue

        return parseRecord(migratedRecord, index, origin)
    } catch {
        return null
    }
}

function hasValidRecordConversationLinks(record, conversations) {
    if (record.type === 'system' || record.details.type !== 'agent') return true
    if (!record.conversationIds.includes(record.rootConversationId)) return false
    const conversation = conversations.find(({ id }) => id === record.rootConversationId)

    return !!conversation && conversation.actionId === record.rootActionId
}

function repairKnownActivityValue(value, expectedOrigin) {
    const origin = expectedOrigin ? parseOrigin(expectedOrigin) : parseOrigin(value.origin)
    const actionSettings = repairActionSettings(value.actionSettings, value.version)
    const rawConversations = Array.isArray(value.conversations) ? value.conversations : []
    const conversations = rawConversations
        .map((conversation, index) => repairConversation(conversation, index, origin))
        .filter((conversation) => conversation !== null)
    const rawRecords = Array.isArray(value.records) ? value.records : []
    const records = rawRecords
        .map((record, index) => repairRecord(record, index, value.version, origin, conversations))
        .filter((record) => record !== null)
        .filter((record) => hasValidRecordConversationLinks(record, conversations))

    return parseActivityValue({ actionSettings, conversations, origin, records, version: ACTIVITY_VERSION }, origin)
}

/** Salvage one activity file without weakening strict parsing used by normal reads and writes. */
export function repairActivityFile(content, expectedOrigin = null) {
    let value
    try {
        value = JSON.parse(content)
    } catch {
        if (!expectedOrigin) return { activity: null, changed: false, status: 'unrecoverable' }

        return { activity: createActivityFile(expectedOrigin), changed: true, status: 'repaired' }
    }
    if (!value || typeof value !== 'object' || Array.isArray(value)) {
        if (!expectedOrigin) return { activity: null, changed: false, status: 'unrecoverable' }

        return { activity: createActivityFile(expectedOrigin), changed: true, status: 'repaired' }
    }
    if (typeof value.version === 'number' && value.version > ACTIVITY_VERSION) {
        return { activity: null, changed: false, status: 'future' }
    }
    if (![LEGACY_ACTIVITY_VERSION, SECOND_ACTIVITY_VERSION, PREVIOUS_ACTIVITY_VERSION, ACTIVITY_VERSION].includes(value.version)) {
        return { activity: null, changed: false, status: 'unrecoverable' }
    }
    if (value.version === ACTIVITY_VERSION) {
        try {
            const activity = parseActivityValue(value, expectedOrigin)

            return { activity, changed: false, status: 'valid' }
        } catch {
            // Continue through tolerant normalization.
        }
    }
    try {
        const activity = repairKnownActivityValue(value, expectedOrigin)

        return { activity, changed: true, status: 'repaired' }
    } catch {
        return { activity: null, changed: false, status: 'unrecoverable' }
    }
}

export function parseActivityFile(content, expectedOrigin = null) {
    return parseActivityValue(JSON.parse(content), expectedOrigin)
}

export function findActivityConversation(activity, conversationId) {
    const conversation = activity.conversations.find(({ id }) => id === conversationId)
    if (!conversation) throw new Error(`Activity conversation not found: ${conversationId}`)
    return conversation
}

        try {
            run.child.stdin.end();
        } catch {
            // Process-tree termination below remains authoritative.
        }

        return this.ensureTermination(run);
    }

    async handleClose(runId, exitCode) {
        const run = this.processes.get(runId);
        if (!run) return;
        this.clearFinishTimeout(run);

        try {
            if (run.termination) await run.termination;
            run.parser?.finish();
            run.protocolLines?.finish();
            await run.protocolHandling;
            this.flushStderr(runId);
            await run.stderrHandling;
            const completedAt = new Date().toISOString();
            if (run.streaming && !run.finishing && !run.cancelled && !run.streamingFailure && !run.suspended) {
                run.streamingFailure = new Error('Streaming agent process exited before Finish');
                const separator = run.stderr.length > 0 && !run.stderr.endsWith('\n') ? '\n' : '';
                run.stderr += `${separator}${run.streamingFailure.message}`;
            }
            const succeeded = (exitCode === 0 || (run.finishing && run.finishForced))
                && !run.missingSession
                && !run.cancelled
                && !run.streamingFailure
                && (!run.streaming || run.finishing);
            completeAssistantOutput(run, completedAt);
            if (succeeded) {
                const synchronizedMessage = lastMessageEntry(run.conversation);
                updateProviderSession(run, synchronizedMessage.id, completedAt);
                if (run.turnUsage) run.conversation.usage = accumulateUsage(run.conversation.usage, run.turnUsage);
                if (!run.streaming && run.turnUsage) await this.recordTokenUsage(run, run.turnUsage, completedAt);
            }
            const preserveWaitingState = run.suspended && run.conversation.status === 'waitingForInput';
            run.conversation.completedAt = preserveWaitingState ? null : completedAt;
            const status = preserveWaitingState
                ? 'waitingForInput'
                : run.cancelled ? 'cancelled' : succeeded ? 'completed' : 'failed';
            transitionConversationStatus(run.conversation, status, completedAt);
            const continuedTurnFailedBeforeStart = !!run.request.conversation
                && !run.turnStarted
                && !succeeded
                && !run.cancelled
                && !run.suspended;
            logAgentEvent('[agent:complete]', {
                completedAt,
                durationMs: Date.parse(completedAt) - Date.parse(run.startedAt),
                actionRunId: run.request.actionRunId ?? null,
                exitCode,
                pid: run.child.pid,
                runId,
            });
            await run.persistence;
            if (!continuedTurnFailedBeforeStart) await this.persistConversation(run);
            this.processes.delete(runId);
            this.runningConversationIds.delete(run.conversation.id);
            emitRunEvent(run, { conversation: run.conversation, type: 'closed' });
            this.requestClaudeUsagePoll(run);
            if (run.onComplete) run.onComplete(succeeded ? 0 : exitCode || 1, run);
        } catch (error) {
            if (run.onCompletionError) run.onCompletionError(error);
        } finally {
            this.processes.delete(runId);
            this.runningConversationIds.delete(run.conversation.id);
        }
    }

    requireRun(runId) {
        const run = this.processes.get(runId);
        if (!run) throw new Error(`Agent run is not active: ${runId}`);

        return run;
    }

    persistCheckpoint(run) {
        const snapshot = { ...run, conversation: snapshotConversation(run.conversation) };
        const write = run.persistence.then(() => this.persistConversationCheckpoint(snapshot));
        run.persistence = write.catch(() => undefined);

        return write;
    }

    requireStreamingRun(runId) {
        const run = this.requireRun(runId);
        if (!run.streaming) throw new Error(`Agent run is not streaming: ${runId}`);

        return run;
    }
}

